{"type":"agent_end","messages":[{"role":"user","content":[{"type":"text","text":"{\"schema\": \"aos-material-review/v1\", \"request_id\": \"qyh-closure-reader-code-r1\", \"task_id\": \"qyh-creator-closure-bounded-reader-20261015\", \"owner\": \"codex-01a13484-f019-7d82-94ce-812396db9124\", \"kind\": \"quality\", \"baseline\": {\"head\": \"2f9362bb8fcf71eb167d8d18630a7d82cdeef824\", \"authority_revision\": \"AOS-002031\", \"files\": {\".evidence/qyh-creator-closure-bounded-reader-20261015/code-review-package-r1.txt\": \"1cb919978f6b12b9d2e80140c92b072aa11d31143d981a7513bc17260333f8ca\"}}, \"claims\": [\"专用reader按单次有界只读snapshot读取四类保存物证，核对原typed哈希、tenant/identity/ref/ledger/time/privacy，失败不能冒充空或完成。\", \"原producer、共享Store和五轴语义保持；本候选的原合同回归及隔离真实PG证据支持代码边界，不替代原真人授权、原650迁移或经营闭环。\"], \"materials\": {\".evidence/qyh-creator-closure-bounded-reader-20261015/code-review-package-r1.txt\": \"CODE QUALITY ONLY, uncommitted four owned files, base2f/Authority2031/current sameowner leases. Original runtime source6bf unchanged/DBreadonly/HostworkerProviderOFF. No code deploy, original nonempty or real approval/business completion claims. Native fixture uses exact4table w6_009 DDL+minimal workspace, never original650 migration.\\n\\nFILE services/aos-api/aos_api/ecommerce_three_module_closure_readonly.py SHA a70090a0c039d159cd72f0de84596baa47caeb8ad81cbb9aebb1210e6cabf3e8\\n\\\"\\\"\\\"Bounded saved creator closure evidence, never compile/bind/consume authority.\\\"\\\"\\\"\\nfrom datetime import datetime\\n\\nimport psycopg\\nfrom psycopg import IsolationLevel\\n\\nfrom aos_api.aip_contracts import HandoffResourceRef, ResourceRef\\nfrom aos_api.db import connect_read_only\\nfrom aos_api.ecommerce_workshop_three_module_closure import (\\n    CompileThreeModuleClosureRequest, EcommerceWorkshopThreeModuleClosureService,\\n    ThreeModule, ThreeModuleClosureRevision, ThreeModuleEffectBindingRevision,\\n    ThreeModuleHandoffBindingRevision, ThreeModuleUsageBindingRevision,\\n    _ledger, canonical_hash,\\n)\\nfrom aos_api.ecommerce_workshop_three_module_closure_store import _STATUS\\nfrom aos_api.public_contracts import redact_sensitive\\n\\nMAX_ITEM_BYTES = 64 * 1024\\nMAX_TOTAL_BYTES = 1024 * 1024\\n_TABLES = {\\n    'closure': ('ecommerce_three_module_closure_revision', ThreeModuleClosureRevision),\\n    'usage': ('ecommerce_three_module_usage_binding_revision', ThreeModuleUsageBindingRevision),\\n    'effect': ('ecommerce_three_module_effect_binding_revision', ThreeModuleEffectBindingRevision),\\n    'handoff': ('ecommerce_three_module_handoff_binding_revision', ThreeModuleHandoffBindingRevision),\\n}\\n\\n\\nclass CreatorClosureReadonlyError(RuntimeError):\\n    def __init__(self, code):\\n        self.code = code\\n        super().__init__(code)\\n\\n\\ndef _deny(suffix):\\n    raise CreatorClosureReadonlyError('CREATOR_CLOSURE_READ_' + suffix)\\n\\n\\ndef _time(value, cutoff):\\n    return isinstance(value, datetime) and value.utcoffset() is not None and value <= cutoff\\n\\n\\ndef _ref_revision(raw):\\n    if type(raw) is not dict or type(raw.get('revision')) is not int or raw['revision'] < 1:\\n        _deny('AUTHORITY_DRIFT')\\n\\n\\ndef _visible(value):\\n    # Typed hashes and derived identities are checked separately; hash digits are\\n    # not contact numbers. Every other public string retains the existing guard.\\n    if isinstance(value, dict):\\n        return {key: _visible(child) for key, child in value.items()\\n                if key not in {'contentHash', 'closureId', 'bindingId'}}\\n    if isinstance(value, list):\\n        return [_visible(child) for child in value]\\n    return value\\n\\n\\nclass _SavedBindings:\\n    def __init__(self, bindings): self.bindings = bindings\\n    def latest_bindings(self, scope, module): return self.bindings\\n\\n\\nclass CreatorClosureReadonlyReader:\\n    def __init__(self, *, connect_factory=None):\\n        self._connect = connect_factory or connect_read_only\\n\\n    @staticmethod\\n    def _row(conn, scope, kind, closure_id=None):\\n        table, _ = _TABLES[kind]\\n        identity = 'closure_id' if kind == 'closure' else 'binding_id'\\n        source = 'source_id' if kind == 'closure' else 'NULL AS source_id'\\n        predicate = 'module=%s' if kind == 'closure' else 'closure_id=%s'\\n        return conn.execute(\\n            f'''SELECT org_id,project_id,{identity} AS resource_id,closure_id,\\n                revision,module,{source},content_hash,created_at,\\n                octet_length(authority_data::text) AS payload_bytes,\\n                CASE WHEN octet_length(authority_data::text)<={MAX_ITEM_BYTES}\\n                     THEN authority_data ELSE NULL END AS authority_data\\n                FROM {table} WHERE org_id=%s AND project_id=%s AND {predicate}\\n                ORDER BY created_at DESC,{identity} LIMIT 1''',\\n            (*scope.key, 'creator' if kind == 'closure' else closure_id),\\n        ).fetchone()\\n\\n    @staticmethod\\n    def _decode(row, scope, kind, cutoff, closure=None):\\n        if (row['org_id'], row['project_id']) != scope.key:\\n            _deny('AUTHORITY_DRIFT')\\n        if (type(row['revision']) is not int or row['revision'] != 1\\n                or not _time(row['created_at'], cutoff)):\\n            _deny('AUTHORITY_DRIFT')\\n        raw = row['authority_data']\\n        if type(raw) is not dict or type(raw.get('revision')) is not int or raw['revision'] != 1:\\n            _deny('AUTHORITY_DRIFT')\\n        model = _TABLES[kind][1]\\n        item = model.model_validate(raw)\\n        if (item.tenant.org_id, item.tenant.project_id) != scope.key:\\n            _deny('AUTHORITY_DRIFT')\\n        if item.content_hash != row['content_hash']:\\n            _deny('AUTHORITY_DRIFT')\\n        if kind == 'closure':\\n            _ref_revision(raw['sourceRef'])\\n            CompileThreeModuleClosureRequest(module='creator', sourceRef=item.source_ref)\\n            identity = 'three-module-closure-' + canonical_hash(\\n                [*scope.key, ThreeModule.CREATOR, item.source_ref.resource_id])[:24]\\n            if (item.module is not ThreeModule.CREATOR or row['module'] != 'creator'\\n                    or row['resource_id'] != identity or item.closure_id != identity\\n                    or row['closure_id'] != identity or row['source_id'] != item.source_ref.resource_id\\n                    or item.compiled_at != row['created_at'] or not _time(item.compiled_at, cutoff)\\n                    or item.ledger != _ledger(item.items)):\\n                _deny('AUTHORITY_DRIFT')\\n            keys = set()\\n            for original, source in zip(item.items, raw['items'], strict=True):\\n                _ref_revision(source['originalRef'])\\n                if source.get('receiptRef') is not None: _ref_revision(source['receiptRef'])\\n                expected = item.source_ref.model_copy(update={\\n                    'resource_id': item.source_ref.resource_id + ':' + original.item_key})\\n                if (original.item_key in keys or original.original_ref != expected\\n                        or _STATUS.get(original.original_status) != original.canonical_outcome):\\n                    _deny('AUTHORITY_DRIFT')\\n                keys.add(original.item_key)\\n            payload = dict(module=item.module, sourceRef=item.source_ref, items=item.items)\\n        else:\\n            _ref_revision(raw['closureRef'])\\n            exact = EcommerceWorkshopThreeModuleClosureService._ref(\\n                'ThreeModuleClosureRevision', closure.closure_id, closure.content_hash)\\n            if (row['module'] not in (None, 'creator') or row['closure_id'] != closure.closure_id\\n                    or item.closure_ref != exact or item.bound_at != row['created_at']\\n                    or not _time(item.bound_at, cutoff) or item.bound_at < closure.compiled_at):\\n                _deny('AUTHORITY_DRIFT')\\n            payload = {'closureRef': item.closure_ref}\\n            if kind == 'usage':\\n                _ref_revision(raw['usageReceiptRef'])\\n                if item.usage_receipt_ref.resource_type != 'UsageReceipt': _deny('AUTHORITY_DRIFT')\\n                payload.update(usageReceiptRef=item.usage_receipt_ref, lineageId=item.lineage_id,\\n                               quality=item.quality, quantity=item.quantity, unit=item.unit,\\n                               adjustmentTotal=item.adjustment_total, settlement=item.settlement)\\n            elif kind == 'effect':\\n                _ref_revision(raw['effectReviewRef'])\\n                if item.effect_review_ref.resource_type != 'EffectReviewRevision': _deny('AUTHORITY_DRIFT')\\n                if (not _time(item.observed_at, item.bound_at)\\n                        or item.cutoff_at.utcoffset() is None\\n                        or (item.maturity_status == 'mature' and item.cutoff_at > item.observed_at)\\n                        or type(raw['accepted']) is not bool or type(raw['effectCompleted']) is not bool):\\n                    _deny('AUTHORITY_DRIFT')\\n                payload.update(effectReviewRef=item.effect_review_ref, maturityStatus=item.maturity_status,\\n                               accepted=item.accepted, effectCompleted=item.effect_completed,\\n                               sampleCount=item.sample_count, minSample=item.min_sample,\\n                               cutoffAt=item.cutoff_at, observedAt=item.observed_at)\\n            else:\\n                _ref_revision(raw['handoffRef'])\\n                if item.handoff_ref.resource_type != 'HandoffEnvelope': _deny('AUTHORITY_DRIFT')\\n                for value, expected_type in [(item.task_ref, 'Task'), (item.task_run_ref, 'TaskRun')]:\\n                    ref_model = HandoffResourceRef if 'contentHash' in value else ResourceRef\\n                    public_ref = ref_model.model_validate(value)\\n                    if public_ref.resource_type != expected_type:\\n                        _deny('CONTENT_UNSUPPORTED')\\n                payload.update(handoffRef=item.handoff_ref, transportStatus=item.transport_status,\\n                               businessDecision=item.business_decision, taskRef=item.task_ref,\\n                               taskRunRef=item.task_run_ref, disclosureRefCount=item.disclosure_ref_count)\\n            identity = 'three-module-' + kind + '-' + canonical_hash(payload)[:24]\\n            if row['resource_id'] != identity or item.binding_id != identity:\\n                _deny('AUTHORITY_DRIFT')\\n        if canonical_hash(payload) != item.content_hash:\\n            _deny('AUTHORITY_DRIFT')\\n        visible = _visible(item.model_dump(mode='json', by_alias=True))\\n        if redact_sensitive(visible) != visible:\\n            _deny('PRIVACY_UNAVAILABLE')\\n        return item\\n\\n    def read(self, scope):\\n        try:\\n            with self._connect(scope) as conn:\\n                if (conn.read_only is not True or conn.autocommit is not False\\n                        or conn.isolation_level != IsolationLevel.REPEATABLE_READ):\\n                    _deny('UNAVAILABLE')\\n                cutoff = conn.execute('SELECT transaction_timestamp() AS cutoff').fetchone()['cutoff']\\n                if not _time(cutoff, cutoff): _deny('AUTHORITY_DRIFT')\\n                bindings, total = dict(closure=None, usage=None, effect=None, handoff=None), 0\\n                for kind in _TABLES:\\n                    if kind != 'closure' and bindings['closure'] is None: break\\n                    row = self._row(conn, scope, kind, getattr(bindings['closure'], 'closure_id', None))\\n                    if row is None: continue\\n                    size = row['payload_bytes']\\n                    if type(size) is not int or size < 1: _deny('AUTHORITY_DRIFT')\\n                    total += size\\n                    if size > MAX_ITEM_BYTES or total > MAX_TOTAL_BYTES: _deny('LIMIT_EXCEEDED')\\n                    bindings[kind] = self._decode(row, scope, kind, cutoff, bindings['closure'])\\n                view = EcommerceWorkshopThreeModuleClosureService(_SavedBindings(bindings)).contribution_view(\\n                    scope, ThreeModule.CREATOR, now=cutoff)\\n                # Revalidate a complete public DTO; no validation-bypassing copy.\\n                data = view.model_dump(mode='json', by_alias=True)\\n                data.update(allowedCommands=[], handoffConsumeAllowed=False,\\n                            memoryPromotionAllowed=False, externalEffectsAllowed=False)\\n                result = type(view).model_validate(data)\\n                if len(result.model_dump_json(by_alias=True).encode()) > MAX_TOTAL_BYTES:\\n                    _deny('LIMIT_EXCEEDED')\\n                return result\\n        except CreatorClosureReadonlyError:\\n            raise\\n        except psycopg.Error:\\n            _deny('UNAVAILABLE')\\n        except (ValueError, KeyError, TypeError, AttributeError):\\n            _deny('AUTHORITY_DRIFT')\\n\\nFILE services/aos-api/tests/test_ecommerce_three_module_closure_readonly.py SHA d573095d816c50f11c5db5dbb76f40081d50c364d25353f44667402b77e57102\\nfrom datetime import UTC, datetime, timedelta\\nimport json\\n\\nimport psycopg\\nimport pytest\\nfrom psycopg import IsolationLevel\\n\\nfrom aos_api.ecommerce_workshop_three_module_closure import (\\n    BindThreeModuleEffectRequest, BindThreeModuleHandoffRequest,\\n    BindThreeModuleUsageRequest, ClosureExactRef, CompileThreeModuleClosureRequest,\\n    EcommerceWorkshopThreeModuleClosureService, ThreeModuleItemOutcome,\\n)\\nfrom aos_api.tenant_scope import TenantScope\\n\\nSCOPE = TenantScope('dev-org', 'fixture-project')\\nNOW = datetime(2026, 10, 15, 1, tzinfo=UTC)\\nCUTOFF = NOW + timedelta(seconds=10)\\nTABLES = dict(closure='ecommerce_three_module_closure_revision',\\n              usage='ecommerce_three_module_usage_binding_revision',\\n              effect='ecommerce_three_module_effect_binding_revision',\\n              handoff='ecommerce_three_module_handoff_binding_revision')\\n\\n\\ndef ref(kind, identity):\\n    return ClosureExactRef(resourceType=kind, resourceId=identity, revision=1,\\n                           contentHash='sha256:' + 'a' * 64, receiptId='receipt-' + identity)\\n\\n\\nclass ProducerFixture:\\n    \\\"\\\"\\\"No DB or real approval: exercise the unchanged original typed producer.\\\"\\\"\\\"\\n    def resolve_domain_items(self, scope, module, source):\\n        return [ThreeModuleItemOutcome(\\n            itemKey=key, originalStatus=status, canonicalOutcome=outcome,\\n            originalRef=source.model_copy(update={'resource_id': source.resource_id + ':' + key}),\\n        ) for key, status, outcome in [('lane-1', 'applied', 'succeeded'),\\n                                     ('lane-2', 'unknown', 'unknown')]]\\n\\n    def append_closure(self, scope, value):\\n        self.closure = value\\n        return value\\n\\n    def require_closure(self, scope, exact):\\n        return self.closure\\n\\n    def resolve_usage(self, scope, identity):\\n        return dict(usageReceiptRef=ref('UsageReceipt', identity), lineageId='fixture-lineage',\\n                    quality='unknown', quantity=None, unit='tokens',\\n                    adjustmentTotal=0.0, settlement='unknown')\\n\\n    def resolve_effect(self, scope, identity, source):\\n        return dict(effectReviewRef=ref('EffectReviewRevision', identity),\\n                    maturityStatus='immature', accepted=True, effectCompleted=False,\\n                    sampleCount=3, minSample=10, cutoffAt=NOW + timedelta(days=1), observedAt=NOW)\\n\\n    def resolve_handoff(self, scope, identity):\\n        return dict(handoffRef=ref('HandoffEnvelope', identity), transportStatus='consumed',\\n                    businessDecision='request_more', disclosureRefCount=0,\\n                    taskRef=dict(resourceType='Task', resourceId='fixture-task', revision='1', authority='postgresql'),\\n                    taskRunRef=dict(resourceType='TaskRun', resourceId='fixture-run', revision='1', authority='postgresql'))\\n\\n    def append_usage_binding(self, scope, value): return value\\n    def append_effect_binding(self, scope, value): return value\\n    def append_handoff_binding(self, scope, value): return value\\n\\n\\ndef authority_rows():\\n    store = ProducerFixture()\\n    service = EcommerceWorkshopThreeModuleClosureService(store)\\n    closure = service.compile(SCOPE, CompileThreeModuleClosureRequest(\\n        module='creator', sourceRef=ref('CreatorBatchStartDecisionRevision', 'fixture-decision')),\\n        'fixture-actor', now=NOW)\\n    exact = service._ref('ThreeModuleClosureRevision', closure.closure_id, closure.content_hash)\\n    values = dict(closure=closure,\\n                  usage=service.bind_usage(SCOPE, BindThreeModuleUsageRequest(closureRef=exact, usageReceiptId='fixture-usage'), now=NOW),\\n                  effect=service.bind_effect(SCOPE, BindThreeModuleEffectRequest(closureRef=exact, effectReviewId='fixture-effect'), now=NOW),\\n                  handoff=service.bind_handoff(SCOPE, BindThreeModuleHandoffRequest(closureRef=exact, handoffId='fixture-handoff'), now=NOW))\\n    rows = {}\\n    for kind, value in values.items():\\n        payload = value.model_dump(mode='json', by_alias=True)\\n        rows[kind] = dict(org_id=SCOPE.org_id, project_id=SCOPE.project_id,\\n                          resource_id=value.closure_id if kind == 'closure' else value.binding_id,\\n                          closure_id=closure.closure_id, revision=1,\\n                          module='creator' if kind == 'closure' else None,\\n                          source_id=closure.source_ref.resource_id if kind == 'closure' else None,\\n                          content_hash=value.content_hash, created_at=NOW,\\n                          payload_bytes=len(json.dumps(payload).encode()), authority_data=payload)\\n    return rows\\n\\n\\nclass Cursor:\\n    def __init__(self, row): self.row = row\\n    def fetchone(self): return self.row\\n\\n\\nclass Connection:\\n    read_only = True\\n    autocommit = False\\n    isolation_level = IsolationLevel.REPEATABLE_READ\\n\\n    def __init__(self, rows): self.rows, self.queries = rows, []\\n    def __enter__(self): return self\\n    def __exit__(self, *args): return False\\n    def execute(self, sql, params=None):\\n        self.queries.append((sql, params))\\n        assert sql.lstrip().upper().startswith('SELECT')\\n        if 'transaction_timestamp()' in sql: return Cursor({'cutoff': CUTOFF})\\n        for kind, table in TABLES.items():\\n            if 'FROM ' + table + ' ' in sql:\\n                assert tuple(params[:2]) == SCOPE.key\\n                return Cursor(self.rows.get(kind))\\n        raise AssertionError('unexpected table')\\n    def commit(self): raise AssertionError('read cannot commit')\\n\\n\\ndef reader(conn):\\n    from aos_api.ecommerce_three_module_closure_readonly import CreatorClosureReadonlyReader\\n    def factory(scope):\\n        assert scope == SCOPE\\n        return conn\\n    return CreatorClosureReadonlyReader(connect_factory=factory)\\n\\n\\ndef denied(conn):\\n    from aos_api.ecommerce_three_module_closure_readonly import CreatorClosureReadonlyError\\n    with pytest.raises(CreatorClosureReadonlyError) as caught:\\n        reader(conn).read(SCOPE)\\n    assert str(caught.value).startswith('CREATOR_CLOSURE_READ_')\\n    return caught.value\\n\\n\\ndef test_empty_has_four_real_gaps_and_no_commands():\\n    conn = Connection({})\\n    view = reader(conn).read(SCOPE)\\n    assert view.latest_closure is None\\n    assert len(view.blockers) == 4 and view.allowed_commands == []\\n    assert view.evaluated_at == CUTOFF and not view.external_effects_allowed\\n    assert not view.handoff_consume_allowed and not view.memory_promotion_allowed\\n\\n\\ndef test_original_producer_hashes_null_module_future_immature_window():\\n    conn = Connection(authority_rows())\\n    view = reader(conn).read(SCOPE)\\n    assert view.latest_closure.ledger.state.value == 'partial'\\n    assert view.latest_usage.quantity is None\\n    assert view.latest_effect.cutoff_at > CUTOFF and not view.latest_effect.effect_completed\\n    assert view.latest_handoff.business_decision == 'request_more'\\n    assert view.allowed_commands == []\\n    assert len(conn.queries) == 5\\n    assert all('CASE WHEN' in sql and 'octet_length' in sql and 'LIMIT 1' in sql\\n               for sql, _ in conn.queries[1:])\\n\\n\\n@pytest.mark.parametrize('kind', list(TABLES))\\n@pytest.mark.parametrize('field,value', [('org_id', 'foreign'), ('project_id', 'foreign'),\\n                                        ('revision', True), ('resource_id', 'foreign'),\\n                                        ('content_hash', 'b' * 64), ('module', 'price'),\\n                                        ('created_at', CUTOFF + timedelta(seconds=1))])\\ndef test_outer_authority_drift_is_not_empty(kind, field, value):\\n    rows = authority_rows(); rows[kind][field] = value\\n    denied(Connection(rows))\\n\\n\\n@pytest.mark.parametrize('kind', list(TABLES))\\ndef test_nested_tenant_drift(kind):\\n    rows = authority_rows(); rows[kind]['authority_data']['tenant']['projectId'] = 'foreign'\\n    denied(Connection(rows))\\n\\n\\n@pytest.mark.parametrize('kind', ['usage', 'effect', 'handoff'])\\ndef test_binding_ref_cannot_borrow_another_closure(kind):\\n    rows = authority_rows(); rows[kind]['authority_data']['closureRef']['resourceId'] = 'foreign'\\n    denied(Connection(rows))\\n\\n\\ndef test_ledger_and_hash_are_both_checked():\\n    rows = authority_rows(); rows['closure']['authority_data']['ledger'] = {\\n        'total': 0, 'inProgress': 0, 'succeeded': 0, 'failed': 0, 'unknown': 0,\\n        'disputed': 0, 'skipped': 0, 'state': 'empty'}\\n    denied(Connection(rows))\\n\\n\\n@pytest.mark.parametrize('kind', list(TABLES))\\ndef test_sql_oversize_sentinel_fails_before_decode(kind):\\n    rows = authority_rows(); rows[kind]['payload_bytes'] = 64 * 1024 + 1\\n    rows[kind]['authority_data'] = None\\n    error = denied(Connection(rows))\\n    assert 'LIMIT' in error.code\\n\\n\\n@pytest.mark.parametrize('field,value', [('read_only', False), ('autocommit', True),\\n                                        ('isolation_level', IsolationLevel.READ_COMMITTED)])\\ndef test_wrong_transaction_is_rejected(field, value):\\n    conn = Connection({}); setattr(conn, field, value)\\n    denied(conn); assert not conn.queries\\n\\n\\ndef test_backend_exception_never_leaks_sql_or_secret():\\n    conn = Connection({})\\n    def fail(*args): raise psycopg.OperationalError('private backend detail')\\n    conn.execute = fail\\n    assert 'private' not in str(denied(conn))\\n\\n\\ndef test_legacy_producer_remains_unchanged():\\n    store = ProducerFixture()\\n    store.latest_bindings = lambda *args: dict(closure=None, usage=None, effect=None, handoff=None)\\n    view = EcommerceWorkshopThreeModuleClosureService(store).contribution_view(SCOPE, 'creator')\\n    assert len(view.allowed_commands) == 4\\n\\n\\n@pytest.mark.parametrize('actor', ['operator@example.invalid', '13800138000'])\\ndef test_sensitive_actor_is_not_returned_even_with_valid_producer_hash(actor):\\n    rows = authority_rows(); rows['closure']['authority_data']['compiledBy'] = actor\\n    assert 'PRIVACY' in denied(Connection(rows)).code\\n\\n\\ndef test_signed_arbitrary_handoff_ref_extension_is_rejected(monkeypatch):\\n    original = ProducerFixture.resolve_handoff\\n    def extended(self, scope, identity):\\n        value = original(self, scope, identity)\\n        value['taskRef']['protectedContact'] = 'must-not-be-disclosed'\\n        return value\\n    monkeypatch.setattr(ProducerFixture, 'resolve_handoff', extended)\\n    denied(Connection(authority_rows()))\\n\\n\\ndef test_signed_wrong_task_ref_kind_is_rejected(monkeypatch):\\n    original = ProducerFixture.resolve_handoff\\n    def wrong(self, scope, identity):\\n        value = original(self, scope, identity)\\n        value['taskRunRef']['resourceType'] = 'ProtectedContact'\\n        return value\\n    monkeypatch.setattr(ProducerFixture, 'resolve_handoff', wrong)\\n    assert 'CONTENT' in denied(Connection(authority_rows())).code\\n\\n\\ndef test_duplicate_signed_items_cannot_double_count(monkeypatch):\\n    original = ProducerFixture.resolve_domain_items\\n    def duplicated(self, scope, module, source):\\n        items = original(self, scope, module, source)\\n        return [items[0], items[0]]\\n    monkeypatch.setattr(ProducerFixture, 'resolve_domain_items', duplicated)\\n    denied(Connection(authority_rows()))\\n\\n\\n@pytest.mark.parametrize('method,key', [('resolve_usage', 'usageReceiptRef'),\\n    ('resolve_effect', 'effectReviewRef'), ('resolve_handoff', 'handoffRef')])\\ndef test_signed_binding_ref_cannot_claim_an_unrelated_authority_kind(monkeypatch, method, key):\\n    original = getattr(ProducerFixture, method)\\n    def wrong(self, *args):\\n        value = original(self, *args)\\n        value[key] = ref('ProtectedContact', 'unrelated-fixture')\\n        return value\\n    monkeypatch.setattr(ProducerFixture, method, wrong)\\n    denied(Connection(authority_rows()))\\n\\nFILE services/aos-api/aos_api/ecommerce_workshop_three_module_closure.py SHA abb7798aae5fe3ca87ec0a05e2445bdbbf16cb54663009709bff20252458ea40\\n\\\"\\\"\\\"W6-09 canonical closure bridge for creator, price and customer modules.\\n\\nThe bridge never accepts caller-declared aggregate success.  Item outcomes,\\nusage, effect maturity and handoff decisions are resolved from their existing\\ntenant authorities and remain five independent axes.\\n\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nimport hashlib\\nimport json\\nfrom datetime import UTC, datetime\\nfrom enum import StrEnum\\nfrom typing import Any\\n\\nfrom pydantic import Field, model_validator\\n\\nfrom aos_api.aip_contracts import AipContractModel, TenantContext\\nfrom aos_api.tenant_scope import TenantScope\\n\\n\\nTHREE_MODULE_CLOSURE_SCHEMA_VERSION = \\\"aos.ecommerce-workshop.three-module-closure/v1\\\"\\n\\n\\ndef canonical_hash(value: Any) -> str:\\n    payload = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(\\\",\\\", \\\":\\\"), default=str)\\n    return hashlib.sha256(payload.encode()).hexdigest()\\n\\n\\nclass ThreeModuleClosureBlocked(RuntimeError):\\n    code = \\\"THREE_MODULE_CLOSURE_BLOCKED\\\"\\n\\n\\nclass ThreeModuleClosureConflict(ThreeModuleClosureBlocked):\\n    code = \\\"THREE_MODULE_CLOSURE_CONFLICT\\\"\\n\\n\\nclass ThreeModule(StrEnum):\\n    CREATOR = \\\"creator\\\"\\n    PRICE = \\\"price\\\"\\n    CUSTOMER = \\\"customer\\\"\\n\\n\\nclass CanonicalItemOutcome(StrEnum):\\n    IN_PROGRESS = \\\"in_progress\\\"\\n    SUCCEEDED = \\\"succeeded\\\"\\n    FAILED = \\\"failed\\\"\\n    UNKNOWN = \\\"unknown\\\"\\n    DISPUTED = \\\"disputed\\\"\\n    SKIPPED = \\\"skipped\\\"\\n\\n\\nclass ClosureState(StrEnum):\\n    EMPTY = \\\"empty\\\"\\n    IN_PROGRESS = \\\"in_progress\\\"\\n    COMPLETED = \\\"completed\\\"\\n    FAILED = \\\"failed\\\"\\n    PARTIAL = \\\"partial\\\"\\n    UNKNOWN = \\\"unknown\\\"\\n\\n\\nclass ClosureExactRef(AipContractModel):\\n    resource_type: str = Field(min_length=1, max_length=120)\\n    resource_id: str = Field(min_length=1, max_length=240)\\n    revision: int = Field(ge=1)\\n    content_hash: str = Field(pattern=r\\\"^sha256:[0-9a-f]{64}$\\\")\\n    receipt_id: str = Field(min_length=1, max_length=240)\\n\\n\\nclass CompileThreeModuleClosureRequest(AipContractModel):\\n    module: ThreeModule\\n    source_ref: ClosureExactRef\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _source_type(self) -> \\\"CompileThreeModuleClosureRequest\\\":\\n        expected = {\\n            ThreeModule.CREATOR: \\\"CreatorBatchStartDecisionRevision\\\",\\n            ThreeModule.PRICE: \\\"PriceDispositionRevision\\\",\\n            ThreeModule.CUSTOMER: \\\"CustomerBatchStartDecisionRevision\\\",\\n        }\\n        if self.source_ref.resource_type != expected[self.module]:\\n            raise ValueError(\\\"three-module sourceRef type drifted\\\")\\n        return self\\n\\n\\nclass ThreeModuleItemOutcome(AipContractModel):\\n    item_key: str = Field(min_length=1, max_length=240)\\n    original_status: str = Field(min_length=1, max_length=80)\\n    canonical_outcome: CanonicalItemOutcome\\n    original_ref: ClosureExactRef\\n    receipt_ref: ClosureExactRef | None = None\\n\\n\\nclass ThreeModuleClosureLedger(AipContractModel):\\n    total: int = Field(ge=0)\\n    in_progress: int = Field(ge=0)\\n    succeeded: int = Field(ge=0)\\n    failed: int = Field(ge=0)\\n    unknown: int = Field(ge=0)\\n    disputed: int = Field(ge=0)\\n    skipped: int = Field(ge=0)\\n    state: ClosureState\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _conserved(self) -> \\\"ThreeModuleClosureLedger\\\":\\n        values = [self.in_progress, self.succeeded, self.failed, self.unknown, self.disputed, self.skipped]\\n        if self.total != sum(values):\\n            raise ValueError(\\\"three-module closure ledger must conserve items\\\")\\n        nonzero = sum(value > 0 for value in values)\\n        expected = (\\n            ClosureState.EMPTY if self.total == 0 else\\n            ClosureState.COMPLETED if self.succeeded == self.total else\\n            ClosureState.FAILED if self.failed == self.total else\\n            ClosureState.UNKNOWN if self.unknown == self.total else\\n            ClosureState.IN_PROGRESS if self.in_progress == self.total else\\n            ClosureState.PARTIAL if nonzero > 1 else\\n            ClosureState.PARTIAL\\n        )\\n        if self.state is not expected:\\n            raise ValueError(\\\"three-module closure state does not match item algebra\\\")\\n        return self\\n\\n\\nclass ThreeModuleClosureRevision(AipContractModel):\\n    tenant: TenantContext\\n    closure_id: str\\n    revision: int = 1\\n    module: ThreeModule\\n    source_ref: ClosureExactRef\\n    items: list[ThreeModuleItemOutcome] = Field(default_factory=list, max_length=2000)\\n    ledger: ThreeModuleClosureLedger\\n    content_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n    compiled_by: str\\n    compiled_at: datetime\\n\\n\\nclass BindThreeModuleUsageRequest(AipContractModel):\\n    closure_ref: ClosureExactRef\\n    usage_receipt_id: str = Field(min_length=1, max_length=240)\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _closure(self) -> \\\"BindThreeModuleUsageRequest\\\":\\n        if self.closure_ref.resource_type != \\\"ThreeModuleClosureRevision\\\":\\n            raise ValueError(\\\"closureRef drifted\\\")\\n        return self\\n\\n\\nclass ThreeModuleUsageBindingRevision(AipContractModel):\\n    tenant: TenantContext\\n    binding_id: str\\n    revision: int = 1\\n    closure_ref: ClosureExactRef\\n    usage_receipt_ref: ClosureExactRef\\n    lineage_id: str\\n    quality: str = Field(pattern=r\\\"^(measured|estimated|unknown)$\\\")\\n    quantity: float | None = Field(default=None, ge=0)\\n    unit: str\\n    adjustment_total: float = 0\\n    settlement: str = Field(pattern=r\\\"^(measured|estimated|unknown)$\\\")\\n    content_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n    bound_at: datetime\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _unknown_has_no_quantity(self) -> \\\"ThreeModuleUsageBindingRevision\\\":\\n        if self.quality == \\\"unknown\\\" and self.quantity is not None:\\n            raise ValueError(\\\"unknown usage cannot invent zero or quantity\\\")\\n        if self.quality != \\\"unknown\\\" and self.quantity is None:\\n            raise ValueError(\\\"known usage requires canonical quantity\\\")\\n        return self\\n\\n\\nclass BindThreeModuleEffectRequest(AipContractModel):\\n    closure_ref: ClosureExactRef\\n    effect_review_id: str = Field(min_length=1, max_length=240)\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _closure(self) -> \\\"BindThreeModuleEffectRequest\\\":\\n        if self.closure_ref.resource_type != \\\"ThreeModuleClosureRevision\\\":\\n            raise ValueError(\\\"closureRef drifted\\\")\\n        return self\\n\\n\\nclass ThreeModuleEffectBindingRevision(AipContractModel):\\n    tenant: TenantContext\\n    binding_id: str\\n    revision: int = 1\\n    closure_ref: ClosureExactRef\\n    effect_review_ref: ClosureExactRef\\n    maturity_status: str = Field(pattern=r\\\"^(immature|mature|insufficient|unknown)$\\\")\\n    accepted: bool\\n    effect_completed: bool\\n    sample_count: int = Field(ge=0)\\n    min_sample: int = Field(ge=1)\\n    cutoff_at: datetime\\n    observed_at: datetime\\n    content_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n    bound_at: datetime\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _maturity_is_honest(self) -> \\\"ThreeModuleEffectBindingRevision\\\":\\n        if self.effect_completed != (self.maturity_status == \\\"mature\\\"):\\n            raise ValueError(\\\"effectCompleted must follow canonical maturity only\\\")\\n        return self\\n\\n\\nclass BindThreeModuleHandoffRequest(AipContractModel):\\n    closure_ref: ClosureExactRef\\n    handoff_id: str = Field(min_length=1, max_length=240)\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _closure(self) -> \\\"BindThreeModuleHandoffRequest\\\":\\n        if self.closure_ref.resource_type != \\\"ThreeModuleClosureRevision\\\":\\n            raise ValueError(\\\"closureRef drifted\\\")\\n        return self\\n\\n\\nclass ThreeModuleHandoffBindingRevision(AipContractModel):\\n    tenant: TenantContext\\n    binding_id: str\\n    revision: int = 1\\n    closure_ref: ClosureExactRef\\n    handoff_ref: ClosureExactRef\\n    transport_status: str\\n    business_decision: str | None = Field(default=None, pattern=r\\\"^(accepted|rejected|request_more|returned)$\\\")\\n    task_ref: dict[str, Any]\\n    task_run_ref: dict[str, Any]\\n    disclosure_ref_count: int = Field(ge=0)\\n    content_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n    bound_at: datetime\\n\\n\\nclass ThreeModuleClosureContributionView(AipContractModel):\\n    schema_version: str = THREE_MODULE_CLOSURE_SCHEMA_VERSION\\n    tenant: TenantContext\\n    module: ThreeModule\\n    evaluated_at: datetime\\n    atomic_skill_ids: list[str]\\n    logic_id: str\\n    primary_colleague: str\\n    collaborator_colleagues: list[str]\\n    latest_closure: ThreeModuleClosureRevision | None\\n    latest_usage: ThreeModuleUsageBindingRevision | None\\n    latest_effect: ThreeModuleEffectBindingRevision | None\\n    latest_handoff: ThreeModuleHandoffBindingRevision | None\\n    blockers: list[str]\\n    allowed_commands: list[str] = Field(default_factory=lambda: [\\n        \\\"COMPILE_THREE_MODULE_CLOSURE\\\",\\n        \\\"BIND_CANONICAL_USAGE\\\",\\n        \\\"BIND_CANONICAL_EFFECT_REVIEW\\\",\\n        \\\"BIND_CANONICAL_HANDOFF\\\",\\n    ])\\n    handoff_consume_allowed: bool = False\\n    memory_promotion_allowed: bool = False\\n    external_effects_allowed: bool = False\\n\\n\\n_CONTRIBUTION = {\\n    ThreeModule.CREATOR: (\\n        [\\\"creator-batch-prepare\\\", \\\"creator-lane-reconcile\\\", \\\"creator-relationship-review\\\"],\\n        \\\"ecommerce-creator-growth\\\",\\n        \\\"达人运营官\\\",\\n        [\\\"内容官\\\", \\\"数据参谋\\\"],\\n    ),\\n    ThreeModule.PRICE: (\\n        [\\\"compile-price-case\\\", \\\"prepare-price-handoff\\\", \\\"evaluate-price-effect\\\"],\\n        \\\"ecommerce-price-governance\\\",\\n        \\\"数据参谋\\\",\\n        [\\\"活动策划师\\\", \\\"导购顾问\\\"],\\n    ),\\n    ThreeModule.CUSTOMER: (\\n        [\\\"segment-customers\\\", \\\"design-customer-journey\\\", \\\"evaluate-dialogue-effect\\\"],\\n        \\\"ecommerce-customer-relationship\\\",\\n        \\\"私域管家\\\",\\n        [\\\"内容官\\\", \\\"客服专员\\\", \\\"导购顾问\\\", \\\"数据参谋\\\"],\\n    ),\\n}\\n\\n\\ndef _ledger(items: list[ThreeModuleItemOutcome]) -> ThreeModuleClosureLedger:\\n    counts = {value.value: 0 for value in CanonicalItemOutcome}\\n    for item in items:\\n        counts[item.canonical_outcome.value] += 1\\n    total = len(items)\\n    nonzero = sum(value > 0 for value in counts.values())\\n    state = (\\n        ClosureState.EMPTY if total == 0 else\\n        ClosureState.COMPLETED if counts[\\\"succeeded\\\"] == total else\\n        ClosureState.FAILED if counts[\\\"failed\\\"] == total else\\n        ClosureState.UNKNOWN if counts[\\\"unknown\\\"] == total else\\n        ClosureState.IN_PROGRESS if counts[\\\"in_progress\\\"] == total else\\n        ClosureState.PARTIAL if nonzero > 1 else\\n        ClosureState.PARTIAL\\n    )\\n    return ThreeModuleClosureLedger(total=total, state=state, **counts)\\n\\n\\nclass EcommerceWorkshopThreeModuleClosureService:\\n    def __init__(self, store: Any) -> None:\\n        self.store = store\\n\\n    @staticmethod\\n    def _tenant(scope: TenantScope) -> TenantContext:\\n        return TenantContext(org_id=scope.org_id, project_id=scope.project_id)\\n\\n    @staticmethod\\n    def _ref(resource_type: str, resource_id: str, content_hash: str) -> ClosureExactRef:\\n        return ClosureExactRef(\\n            resourceType=resource_type,\\n            resourceId=resource_id,\\n            revision=1,\\n            contentHash=f\\\"sha256:{content_hash}\\\",\\n            receiptId=f\\\"receipt-{resource_id}\\\",\\n        )\\n\\n    def compile(self, scope: TenantScope, request: CompileThreeModuleClosureRequest, actor: str, *, now: datetime | None = None) -> ThreeModuleClosureRevision:\\n        at = now or datetime.now(UTC)\\n        items = self.store.resolve_domain_items(scope, request.module, request.source_ref)\\n        payload = {\\\"module\\\": request.module, \\\"sourceRef\\\": request.source_ref, \\\"items\\\": items}\\n        content_hash = canonical_hash(payload)\\n        closure_id = f\\\"three-module-closure-{canonical_hash([*scope.key, request.module, request.source_ref.resource_id])[:24]}\\\"\\n        item = ThreeModuleClosureRevision(\\n            tenant=self._tenant(scope), closureId=closure_id, module=request.module,\\n            sourceRef=request.source_ref, items=items, ledger=_ledger(items),\\n            contentHash=content_hash, compiledBy=actor, compiledAt=at,\\n        )\\n        return self.store.append_closure(scope, item)\\n\\n    def require_closure(self, scope: TenantScope, ref: ClosureExactRef) -> ThreeModuleClosureRevision:\\n        return self.store.require_closure(scope, ref)\\n\\n    def bind_usage(self, scope: TenantScope, request: BindThreeModuleUsageRequest, *, now: datetime | None = None) -> ThreeModuleUsageBindingRevision:\\n        at = now or datetime.now(UTC)\\n        self.store.require_closure(scope, request.closure_ref)\\n        resolved = self.store.resolve_usage(scope, request.usage_receipt_id)\\n        payload = {\\\"closureRef\\\": request.closure_ref, **resolved}\\n        content_hash = canonical_hash(payload)\\n        item = ThreeModuleUsageBindingRevision(\\n            tenant=self._tenant(scope), bindingId=f\\\"three-module-usage-{content_hash[:24]}\\\",\\n            closureRef=request.closure_ref, contentHash=content_hash, boundAt=at, **resolved,\\n        )\\n        return self.store.append_usage_binding(scope, item)\\n\\n    def bind_effect(self, scope: TenantScope, request: BindThreeModuleEffectRequest, *, now: datetime | None = None) -> ThreeModuleEffectBindingRevision:\\n        at = now or datetime.now(UTC)\\n        closure = self.store.require_closure(scope, request.closure_ref)\\n        resolved = self.store.resolve_effect(scope, request.effect_review_id, closure.source_ref)\\n        payload = {\\\"closureRef\\\": request.closure_ref, **resolved}\\n        content_hash = canonical_hash(payload)\\n        item = ThreeModuleEffectBindingRevision(\\n            tenant=self._tenant(scope), bindingId=f\\\"three-module-effect-{content_hash[:24]}\\\",\\n            closureRef=request.closure_ref, contentHash=content_hash, boundAt=at, **resolved,\\n        )\\n        return self.store.append_effect_binding(scope, item)\\n\\n    def bind_handoff(self, scope: TenantScope, request: BindThreeModuleHandoffRequest, *, now: datetime | None = None) -> ThreeModuleHandoffBindingRevision:\\n        at = now or datetime.now(UTC)\\n        self.store.require_closure(scope, request.closure_ref)\\n        resolved = self.store.resolve_handoff(scope, request.handoff_id)\\n        payload = {\\\"closureRef\\\": request.closure_ref, **resolved}\\n        content_hash = canonical_hash(payload)\\n        item = ThreeModuleHandoffBindingRevision(\\n            tenant=self._tenant(scope), bindingId=f\\\"three-module-handoff-{content_hash[:24]}\\\",\\n            closureRef=request.closure_ref, contentHash=content_hash, boundAt=at, **resolved,\\n        )\\n        return self.store.append_handoff_binding(scope, item)\\n\\n    def contribution_view(self, scope: TenantScope, module: ThreeModule, *, now: datetime | None = None) -> ThreeModuleClosureContributionView:\\n        at = now or datetime.now(UTC)\\n        latest = self.store.latest_bindings(scope, module)\\n        skills, logic, primary, collaborators = _CONTRIBUTION[module]\\n        closure = latest[\\\"closure\\\"]\\n        blockers: list[str] = []\\n        if closure is None:\\n            blockers.append(\\\"THREE_MODULE_CLOSURE_NOT_COMPILED\\\")\\n        if latest[\\\"usage\\\"] is None:\\n            blockers.append(\\\"THREE_MODULE_USAGE_NOT_BOUND\\\")\\n        if latest[\\\"effect\\\"] is None:\\n            blockers.append(\\\"THREE_MODULE_EFFECT_NOT_BOUND\\\")\\n        elif latest[\\\"effect\\\"].maturity_status != \\\"mature\\\":\\n            blockers.append(f\\\"THREE_MODULE_EFFECT_{latest['effect'].maturity_status.upper()}\\\")\\n        if latest[\\\"handoff\\\"] is None:\\n            blockers.append(\\\"THREE_MODULE_HANDOFF_N